import{_ as e,a as r,b as o,c as d,d as i}from"./chunks/error-05.D7FyJuqe.js";import{_ as a,o as n,c as l,a3 as s}from"./chunks/framework.D1iekJsc.js";const v=JSON.parse('{"title":"오류 코드","description":"MiniTavern 연결 테스트·채팅 오류 코드 대조표 — invalidApiKey, rateLimit, visionUnsupported 등 원인과 해결.","frontmatter":{"title":"오류 코드","description":"MiniTavern 연결 테스트·채팅 오류 코드 대조표 — invalidApiKey, rateLimit, visionUnsupported 등 원인과 해결.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"오류 코드 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 연결 테스트·채팅 오류 코드 대조표 — invalidApiKey, rateLimit, visionUnsupported 등 원인과 해결."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/manual/errors"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/manual/errors"}]]},"headers":[],"relativePath":"ko/manual/errors.md","filePath":"ko/manual/errors.md","lastUpdated":1787816217000}'),c={name:"ko/manual/errors.md"};function u(h,t,p,g,m,f){return n(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="오류-코드" tabindex="-1">오류 코드 <a class="header-anchor" href="#오류-코드" aria-label="Permalink to &quot;오류 코드&quot;">​</a></h1><p>연결 테스트 실패 또는 채팅 버블 오류 시 <strong>상세 보기</strong>를 눌러 본 페이지의 <strong>오류 코드</strong>（또는 문구 키워드）와 대조하세요.</p><p>상세에는 보통 다음이 있습니다:</p><ul><li><strong>오류 코드</strong>（영문 식별자, 예 <code>invalidApiKey</code>）</li><li><strong>오류 원인</strong></li><li><strong>시도할 수정</strong></li></ul><p>아래 「코드」는 App 오류 상세에 표시되는 이름을 기준으로 합니다.</p><hr><h2 id="빠른-대조표" tabindex="-1">빠른 대조표 <a class="header-anchor" href="#빠른-대조표" aria-label="Permalink to &quot;빠른 대조표&quot;">​</a></h2><table tabindex="0"><thead><tr><th>오류 코드</th><th>사용자에게 보이는 요약</th><th>우선 처리</th></tr></thead><tbody><tr><td><code>missingApiKey</code></td><td>API Key를 먼저 입력하세요</td><td>모델 연결에 키 입력</td></tr><tr><td><code>invalidApiKey</code></td><td>키가 유효하지 않거나 만료</td><td>복사 완전성 확인; 콘솔에서 재발급</td></tr><tr><td><code>forbidden</code></td><td>접근 거부</td><td>권한, 모델 개통 여부</td></tr><tr><td><code>regionForbidden</code></td><td>지역에서 사용 불가</td><td>네트워크 / 프록시 / 국제 사이트</td></tr><tr><td><code>network</code></td><td>네트워크 연결 실패</td><td>네트워크, Base URL, 방화벽</td></tr><tr><td><code>timeout</code></td><td>요청 시간 초과</td><td>네트워크; 로컬 모델은 타임아웃 증가</td></tr><tr><td><code>modelNotFound</code></td><td>모델이 없음</td><td>모델 ID 확인</td></tr><tr><td><code>modelRetired</code></td><td>모델 오프라인</td><td>목록에서 현재 사용 가능 모델로 변경</td></tr><tr><td><code>rateLimit</code></td><td>요청이 너무 잦음</td><td>대기 후 재시도</td></tr><tr><td><code>freeTierQuota</code></td><td>무료 티어 요청 한도</td><td>Please retry in … 대기; 빈도 낮추거나 유료 업그레이드</td></tr><tr><td><code>insufficientQuota</code></td><td>한도 부족</td><td>충전 / 키 교체</td></tr><tr><td><code>spendingCapExceeded</code></td><td>월 소비 상한</td><td>콘솔에서 spend cap 상향</td></tr><tr><td><code>providerReturnedError</code></td><td>업스트림 오류</td><td>모델 변경 / 같은 벤더 <code>:free</code> 회피 / OpenRouter BYOK</td></tr><tr><td><code>contextLengthExceeded</code></td><td>컨텍스트 초과</td><td>기억 축소; 응답 토큰 None; 큰 컨텍스트 모델</td></tr><tr><td><code>anthropicMaxTokensRequired</code></td><td>Claude에 max_tokens 필요</td><td>모델 설정에서 「응답 토큰」켜기</td></tr><tr><td><code>badRequest</code></td><td>파라미터 오류</td><td>파라미터와 호환 인터페이스 형식 확인</td></tr><tr><td><code>serverError</code></td><td>서버 오류</td><td>잠시 후 재시도</td></tr><tr><td><code>requestFailed</code></td><td>요청 실패</td><td>상세 원문 확인</td></tr><tr><td><code>contentPolicy</code></td><td>안전 심사 미통과</td><td>재생성 / 모델 변경 / 다시 쓰기</td></tr><tr><td><code>emptyContent</code></td><td>응답이 비어 있음</td><td>재시도; 사고 모델 필드 확인</td></tr><tr><td><code>modelAtCapacity</code></td><td>모델 포화</td><td>대기 또는 모델 변경</td></tr><tr><td><code>productNotActivated</code></td><td>제품 미개통</td><td>콘솔에서 모델 개통</td></tr><tr><td><code>visionUnsupported</code></td><td>이미지 미지원</td><td>비전 모델로 바꾸거나 첨부 끄기</td></tr><tr><td><code>textOutputUnsupported</code></td><td>텍스트 대화 미지원</td><td>텍스트 채팅 모델로 변경, TTS/이미지 전용 ID 금지</td></tr></tbody></table><hr><h2 id="분류-상세" tabindex="-1">분류 상세 <a class="header-anchor" href="#분류-상세" aria-label="Permalink to &quot;분류 상세&quot;">​</a></h2><h3 id="missingapikey" tabindex="-1">missingApiKey <a class="header-anchor" href="#missingapikey" aria-label="Permalink to &quot;missingApiKey&quot;">​</a></h3><ul><li><strong>현상</strong>: 키 없이 요청 불가.</li><li><strong>처리</strong>: 설정 → 모델 연결 → API Key. 로컬 Ollama 등은 비어 있지 않은 자리 표시자（검증이 비어 있지 않음을 요구할 때）.</li></ul><h3 id="invalidapikey" tabindex="-1">invalidApiKey <a class="header-anchor" href="#invalidapikey" aria-label="Permalink to &quot;invalidApiKey&quot;">​</a></h3><ul><li><strong>현상</strong>: 401류, 키 무효.</li><li><strong>처리</strong>: 공백 없이 전체 복사; 국내/국제 사이트와 키 일치; 키 재발급.</li></ul><h3 id="forbidden-regionforbidden" tabindex="-1">forbidden / regionForbidden <a class="header-anchor" href="#forbidden-regionforbidden" aria-label="Permalink to &quot;forbidden / regionForbidden&quot;">​</a></h3><ul><li><strong>현상</strong>: 403, 지역 제한.</li><li><strong>처리</strong>: 모델 권한 확인; 프록시 또는 국제 Base URL.</li></ul><h3 id="network-timeout" tabindex="-1">network / timeout <a class="header-anchor" href="#network-timeout" aria-label="Permalink to &quot;network / timeout&quot;">​</a></h3><ul><li><strong>현상</strong>: 연결 불가 또는 장시간 무응답.</li><li><strong>처리</strong>: <ul><li>Base URL 확인（로컬은 폰의 <code>localhost</code> 금지, PC LAN IP）.</li><li>PC 방화벽 포트 개방; 폰과 PC 같은 Wi‑Fi.</li><li>약한 망·느린 로컬 모델: 타임아웃 증가, 작은 모델.</li></ul></li></ul><h3 id="modelnotfound" tabindex="-1">modelNotFound <a class="header-anchor" href="#modelnotfound" aria-label="Permalink to &quot;modelNotFound&quot;">​</a></h3><ul><li><strong>현상</strong>: 모델 ID 오류.</li><li><strong>처리</strong>: 테스트 후 목록에서 다시 선택; 로컬은 <code>ollama list</code> / LM Studio 표시명과 일치.</li></ul><h3 id="modelretired" tabindex="-1">modelRetired <a class="header-anchor" href="#modelretired" aria-label="Permalink to &quot;modelRetired&quot;">​</a></h3><ul><li><strong>현상</strong>: HTTP 404, <code>no longer available to new users</code> / <code>use a newer model</code>（예 <code>models/gemini-2.5-flash-lite</code>）.</li><li><strong>구분</strong>: 벤더가 폐기했거나 신규에 개방하지 않음 — 오타가 아님.</li><li><strong>처리</strong>: 모델 연결에서 최신 목록을 받아 온라인 Gemini（예 <code>gemini-flash-latest</code>）선택. Interactions API로 바꿀 필요 없음. 목록: <a href="https://ai.google.dev/gemini-api/docs/models" target="_blank" rel="noreferrer">Gemini models</a>.</li></ul><h3 id="ratelimit" tabindex="-1">rateLimit <a class="header-anchor" href="#ratelimit" aria-label="Permalink to &quot;rateLimit&quot;">​</a></h3><ul><li><strong>처리</strong>: 전송 빈도 낮추기; 잠시 후 재시도; 요금제 업그레이드.</li></ul><h3 id="freetierquota" tabindex="-1">freeTierQuota <a class="header-anchor" href="#freetierquota" aria-label="Permalink to &quot;freeTierQuota&quot;">​</a></h3><ul><li><strong>현상</strong>: Gemini 등 <code>HTTP 429</code> + <code>generate_content_free_tier_requests</code>（자주 limit: 20）, <code>Please retry in …s</code>.</li><li><strong>구분</strong>: <strong>무료 티어 분당/일일 요청 수</strong> — 잔액 부족이나 프로젝트 월 spend cap이 아님.</li><li><strong>처리</strong>: 안내 초 후 재시도; 빈도 낮추기; <a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">AI Studio 사용량</a>; 더 높은 한도는 결제/유료. 설명: <a href="https://ai.google.dev/gemini-api/docs/rate-limits" target="_blank" rel="noreferrer">Gemini rate limits</a>.</li></ul><h3 id="insufficientquota-spendingcapexceeded" tabindex="-1">insufficientQuota / spendingCapExceeded <a class="header-anchor" href="#insufficientquota-spendingcapexceeded" aria-label="Permalink to &quot;insufficientQuota / spendingCapExceeded&quot;">​</a></h3><ul><li><strong>구분</strong>: 한도 소진 vs <strong>프로젝트 월 소비 상한</strong>（후자는 대기만으로 보통 해결 안 됨）.</li><li><strong>처리</strong>: 충전; 또는 콘솔에서 spend cap 조정（예 Google AI Studio Spend）.</li></ul><h3 id="providerreturnederror" tabindex="-1">providerReturnedError <a class="header-anchor" href="#providerreturnederror" aria-label="Permalink to &quot;providerReturnedError&quot;">​</a></h3><ul><li><strong>현상</strong>: OpenRouter 등 <code>HTTP 429: Provider returned error</code>（<code>:free</code>에서 흔함）.</li><li><strong>처리</strong>: 잠시 후 재시도; 다른 벤더 한가한 모델; 또는 <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">OpenRouter BYOK</a>.</li></ul><h3 id="contextlengthexceeded" tabindex="-1">contextLengthExceeded <a class="header-anchor" href="#contextlengthexceeded" aria-label="Permalink to &quot;contextLengthExceeded&quot;">​</a></h3><ul><li><strong>처리</strong>: 설정 → 모델 설정 → 기억 길이 축소; 「응답 토큰」을 None（해당 시）; 더 큰 컨텍스트 모델.</li></ul><h3 id="anthropicmaxtokensrequired" tabindex="-1">anthropicMaxTokensRequired <a class="header-anchor" href="#anthropicmaxtokensrequired" aria-label="Permalink to &quot;anthropicMaxTokensRequired&quot;">​</a></h3><ul><li><strong>처리</strong>: Claude는 max_tokens 필수 → 모델 설정에서 「응답 토큰」켜기, None 금지.</li></ul><h3 id="badrequest" tabindex="-1">badRequest <a class="header-anchor" href="#badrequest" aria-label="Permalink to &quot;badRequest&quot;">​</a></h3><ul><li><strong>처리</strong>: temperature 등 확인; 제3자 호환 사이트가 진짜 OpenAI/Anthropic 형식인지.</li></ul><h3 id="servererror-requestfailed-modelatcapacity" tabindex="-1">serverError / requestFailed / modelAtCapacity <a class="header-anchor" href="#servererror-requestfailed-modelatcapacity" aria-label="Permalink to &quot;serverError / requestFailed / modelAtCapacity&quot;">​</a></h3><ul><li><strong>처리</strong>: 잠시 후 재시도; 엔드포인트·모델 변경; 지속 시 벤더에 상세 원문 첨부.</li></ul><h3 id="contentpolicy" tabindex="-1">contentPolicy <a class="header-anchor" href="#contentpolicy" aria-label="Permalink to &quot;contentPolicy&quot;">​</a></h3><ul><li><strong>처리</strong>: 재생성, 다시 쓰기, 심사가 느슨한 모델; 일부 NSFW 카드는 출력 차단이 잦음.</li></ul><h3 id="emptycontent" tabindex="-1">emptyContent <a class="header-anchor" href="#emptycontent" aria-label="Permalink to &quot;emptyContent&quot;">​</a></h3><ul><li><strong>처리</strong>: 재시도; 일부 사고 모델은 reasoning만 반환 → 상세의 전체 필드 또는 모델 변경.</li></ul><h3 id="productnotactivated" tabindex="-1">productNotActivated <a class="header-anchor" href="#productnotactivated" aria-label="Permalink to &quot;productNotActivated&quot;">​</a></h3><ul><li><strong>처리</strong>: 클라우드 콘솔에서 해당 제품/모델 개통 후 현재 키 사용.</li></ul><h3 id="visionunsupported" tabindex="-1">visionUnsupported <a class="header-anchor" href="#visionunsupported" aria-label="Permalink to &quot;visionUnsupported&quot;">​</a></h3><ul><li><strong>처리</strong>: 비전 지원 모델로; 또는 이미지 보내지 않기 / 이미지 인식 묘사로 순수 텍스트 묘사.</li></ul><h3 id="textoutputunsupported" tabindex="-1">textOutputUnsupported <a class="header-anchor" href="#textoutputunsupported" aria-label="Permalink to &quot;textOutputUnsupported&quot;">​</a></h3><ul><li><strong>현상</strong>: HTTP 400, <code>response modalities</code>와 <code>TEXT</code> 미지원（예 <code>models/gemini-2.5-flash-preview-tts</code>는 <code>AUDIO</code>만）.</li><li><strong>구분</strong>: TTS / 이미지 전용 모델을 채팅 테스트에 씀 — 키·샘플링 오타가 아님.</li><li><strong>처리</strong>: 모델 연결에서 텍스트 채팅 모델（예 <code>gemini-flash-latest</code>）. 이름에 <code>tts</code>·<code>image</code>가 있는 전용 ID 금지. 음성·이미지는 해당 기능에서 설정.</li></ul><hr><h2 id="로컬-모델-전용" tabindex="-1">로컬 모델 전용 <a class="header-anchor" href="#로컬-모델-전용" aria-label="Permalink to &quot;로컬 모델 전용&quot;">​</a></h2><p>PC의 Ollama / LM Studio에 연결되지 않으면: <a href="/ultra_guides/ko/troubleshoot">로컬 문제 해결</a>.</p><p>App 테스트 / 채팅 오류（오류 코드 포함）: <a href="/ultra_guides/ko/manual/errors">매뉴얼 · 오류 코드</a>.</p><div class="tip custom-block"><p class="custom-block-title">스크린샷</p><div class="shot-flow"><figure class="shot-step"><img src="'+e+'" alt="말풍선 오류"><figcaption>1 · 말풍선 오류</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="상세 보기"><figcaption>2 · 상세 보기</figcaption></figure><figure class="shot-step"><img src="'+o+'" alt="오류 상세"><figcaption>3 · 코드와 원인</figcaption></figure><figure class="shot-step"><img src="'+d+'" alt="수정 시도"><figcaption>4 · 수정 힌트</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="이 페이지 대조"><figcaption>5 · 이 페이지와 대조</figcaption></figure></div></div>',53)])])}const k=a(c,[["render",u]]);export{v as __pageData,k as default};
